export type LegendEntry = {
  id: string;
  label: string;
  /** The colour of the mark. The label keeps a text colour. */
  color: string;
  /** A series taken off the plot keeps its place and its colour, faded. */
  isOff?: boolean;
};

function keyOpacityOf(isOff: boolean | undefined) {
  if (isOff) {
    return 'opacity-30';
  }
  return undefined;
}

function labelToneOf(isOff: boolean | undefined) {
  if (isOff) {
    return 'text-muted-foreground';
  }
  return 'text-foreground';
}

function LegendKey({ entry }: { entry: LegendEntry }) {
  return (
    <span
      aria-hidden='true'
      className={cn(
        'h-0.5 w-3 shrink-0 rounded-full transition-opacity duration-150',
        keyOpacityOf(entry.isOff)
      )}
      style={{ backgroundColor: entry.color }}
    />
  );
}

type LegendProps = {
  entries: readonly LegendEntry[];
  /** What the list names, for screen readers. */
  label: string;
  /** With it each entry is a button that takes its series off the plot and puts it back. */
  onToggle?: (id: string) => void;
  /** The entry a demonstration is pressing. */
  pressedId?: string | null;
  className?: string;
};

export function Legend({
  entries,
  label,
  onToggle,
  pressedId = null,
  className,
}: LegendProps) {
  return (
    <ul
      aria-label={label}
      className={cn('-mx-1.5 flex flex-wrap gap-x-1 gap-y-0.5', className)}
    >
      {entries.map((entry) => (
        <li key={entry.id}>
          {onToggle && (
            <button
              type='button'
              aria-pressed={!entry.isOff}
              onClick={() => onToggle(entry.id)}
              className={cn(
                'hover:bg-foreground/5 focus-visible:ring-ring/25 flex h-7 cursor-pointer items-center gap-2 rounded-md px-1.5 text-xs outline-none',
                'transition-[color,background-color,scale] duration-150 ease-(--ease-out-strong) focus-visible:ring-[3px] active:scale-[0.97]',
                labelToneOf(entry.isOff),
                pressedQuietOf(entry.id === pressedId)
              )}
            >
              <LegendKey entry={entry} />
              {entry.label}
            </button>
          )}
          {!onToggle && (
            <span className='flex h-7 items-center gap-2 px-1.5 text-xs'>
              <LegendKey entry={entry} />
              {entry.label}
            </span>
          )}
        </li>
      ))}
    </ul>
  );
}

'use client';

import { motion, type Transition } from 'motion/react';
import { useState } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { EASE_OUT_STRONG, INSTANT } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';

const MORPH: Transition = { duration: 0.3, ease: EASE_OUT_STRONG };

/** What is there on mount does not fade in: only a shape that replaced another one does. */
const SWAP_FADE =
  'transition-opacity duration-200 ease-(--ease-out-strong) starting:opacity-0';

function transitionOf(isInstant: boolean) {
  if (isInstant) {
    return INSTANT;
  }
  return MORPH;
}

function swapFadeOf(hasChanged: boolean) {
  if (hasChanged) {
    return SWAP_FADE;
  }
  return undefined;
}

/** False until the value changes for the first time. */
function useHasChanged(value: string) {
  const [firstValue] = useState(value);
  const [hasChanged, setHasChanged] = useState(false);
  const isFirstChange = value !== firstValue && !hasChanged;
  if (isFirstChange) {
    setHasChanged(true);
  }
  return hasChanged;
}

type MorphPathProps = {
  d: string;
  /** True while the shape follows a hand: it is redrawn where the hand is, with no glide behind it. */
  isInstant?: boolean;
  className?: string;
  style?: React.CSSProperties;
  /** For a shape that is its own hit target. */
  onPointerEnter?: () => void;
};

/**
 * A shape that glides to its new outline when the data changes, as long as both outlines have the
 * same number of points. Under reduced motion the new shape replaces the old one with a fade.
 */
export function MorphPath({
  d,
  isInstant = false,
  className,
  style,
  onPointerEnter,
}: MorphPathProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const hasChanged = useHasChanged(d);

  if (shouldReduceMotion) {
    return (
      <path
        key={d}
        d={d}
        vectorEffect='non-scaling-stroke'
        className={cn(swapFadeOf(hasChanged), className)}
        style={style}
        onPointerEnter={onPointerEnter}
      />
    );
  }

  return (
    <motion.path
      initial={false}
      animate={{ d }}
      transition={transitionOf(isInstant)}
      vectorEffect='non-scaling-stroke'
      className={className}
      style={style}
      onPointerEnter={onPointerEnter}
    />
  );
}

/** The stroke of a line: 2px whatever the width of the plot, with round joins and ends. */
export const LINE_STROKE =
  'fill-none stroke-2 [stroke-linecap:round] [stroke-linejoin:round]';

import { columnCenterOf, lerp, ratioOf, type Domain } from './scale';

export type Point = {
  x: number;
  y: number;
};

/** Paths are drawn in a box this wide and stretched to the plot, so a change of width never redraws them. */
export const VIEW_WIDTH = 1000;

function commandOf(point: Point, index: number) {
  const x = point.x.toFixed(1);
  const y = point.y.toFixed(1);
  if (index === 0) {
    return `M${x} ${y}`;
  }
  return `L${x} ${y}`;
}

export function linePathOf(points: readonly Point[]) {
  const commands = points.map((point, index) => commandOf(point, index));
  return commands.join(' ');
}

/** The line closed down (or up) to a level, for the wash under a line. */
export function areaPathOf(points: readonly Point[], levelY: number) {
  if (points.length === 0) {
    return '';
  }
  const line = linePathOf(points);
  const lastIndex = points.length - 1;
  const firstX = points[0].x.toFixed(1);
  const lastX = points[lastIndex].x.toFixed(1);
  const level = levelY.toFixed(1);
  return `${line} L${lastX} ${level} L${firstX} ${level} Z`;
}

/** The surface between two lines that share their x positions, for a range around a line. */
export function bandPathOf(upper: readonly Point[], lower: readonly Point[]) {
  if (upper.length === 0) {
    return '';
  }
  const backwards = [...lower].reverse();
  const outline = [...upper, ...backwards];
  const line = linePathOf(outline);
  return `${line} Z`;
}

/** The pixel height of a value in a plot: the top of the domain is 0, its bottom is the plot height. */
export function yOf(value: number, domain: Domain, height: number) {
  const ratio = ratioOf(value, domain);
  const fromBottom = ratio * height;
  return height - fromBottom;
}

/** One point per value, each in the middle of its column. */
export function plotPointsOf(
  values: readonly number[],
  domain: Domain,
  height: number
): Point[] {
  return values.map((value, index) => {
    const share = columnCenterOf(index, values.length);
    const x = share * VIEW_WIDTH;
    const y = yOf(value, domain, height);
    return { x, y };
  });
}

/** How many of the pieces lie before a segment when they are shared out evenly. */
function piecesBefore(
  segment: number,
  segmentCount: number,
  pieceCount: number
) {
  const share = segment / segmentCount;
  return Math.floor(share * pieceCount);
}

/**
 * The same line through exactly `count` points: each segment is cut into equal parts, so two lines
 * of different lengths share one structure and one can glide into the other.
 */
export function densifyOf(points: readonly Point[], count: number): Point[] {
  const segmentCount = points.length - 1;
  const hasSegments = segmentCount >= 1;
  const hasRoom = count > points.length;
  if (!hasSegments || !hasRoom) {
    return [...points];
  }
  const pieceCount = count - 1;
  const dense: Point[] = [points[0]];
  for (let segment = 0; segment < segmentCount; segment += 1) {
    const from = points[segment];
    const to = points[segment + 1];
    const start = piecesBefore(segment, segmentCount, pieceCount);
    const end = piecesBefore(segment + 1, segmentCount, pieceCount);
    const parts = end - start;
    for (let part = 1; part <= parts; part += 1) {
      const amount = part / parts;
      const x = lerp(from.x, to.x, amount);
      const y = lerp(from.y, to.y, amount);
      dense.push({ x, y });
    }
  }
  return dense;
}

import { cn } from '@/registry/ndeko/lib/utils';

import { CategoryAxis, GridLines, ValueAxis, type AxisLabel } from './axis';
import { VIEW_WIDTH } from './path';
import type { Scale } from './scale';

/**
 * A plot is a query container, so the readout and the marks inside it are placed in shares of its
 * width, and it lets the page scroll vertically under a finger while a sideways move reads values.
 */
export const PLOT_SURFACE =
  'focus-visible:ring-ring/25 @container relative touch-pan-y rounded-md outline-none focus-visible:ring-[3px]';

type PlotFrameProps = {
  /** The name of the plot and how to read it, for screen readers. */
  label: string;
  scale: Scale;
  height: number;
  formatTick: (value: number) => string;
  axisLabels: readonly AxisLabel[];
  axisAlign?: 'spread' | 'center';
  /** Receives the plot element, for a chart that measures the room it has. */
  plotRef?: (element: HTMLDivElement | null) => void;
  /** The handlers of the reading: the plot is the one tab stop of the chart. */
  plotProps?: React.HTMLAttributes<HTMLDivElement>;
  plotClassName?: string;
  /** For a chart whose marks carry their own figures, which can drop the axis on a narrow piece. */
  valueAxisClassName?: string;
  /** Labels laid out by the chart itself, in place of one row of `axisLabels`. */
  categoryAxis?: React.ReactNode;
  className?: string;
  children: React.ReactNode;
};

/**
 * A plot between its value axis on the left and its category axis underneath. Each part has its own
 * cell: placed in turn, a plot whose value axis is hidden would fall into the axis column, which is
 * only as wide as its content, and nothing in a plot has a width of its own, so every mark would
 * stack at the left edge.
 */
export function PlotFrame({
  label,
  scale,
  height,
  formatTick,
  axisLabels,
  axisAlign,
  plotRef,
  plotProps,
  plotClassName,
  valueAxisClassName,
  categoryAxis,
  className,
  children,
}: PlotFrameProps) {
  return (
    <div
      className={cn('grid grid-cols-[auto_minmax(0,1fr)] gap-x-2', className)}
    >
      <ValueAxis
        scale={scale}
        height={height}
        format={formatTick}
        className={cn('col-start-1 row-start-1', valueAxisClassName)}
      />
      <div
        ref={plotRef}
        role='group'
        tabIndex={0}
        aria-label={label}
        className={cn(PLOT_SURFACE, 'col-start-2 row-start-1', plotClassName)}
        style={{ height }}
        {...plotProps}
      >
        <GridLines scale={scale} height={height} />
        {children}
      </div>
      <div className='col-start-2 row-start-2 min-w-0'>
        {categoryAxis}
        {!categoryAxis && (
          <CategoryAxis
            labels={axisLabels}
            align={axisAlign}
            className='mt-2'
          />
        )}
      </div>
    </div>
  );
}

type PathLayerProps = {
  height: number;
  className?: string;
  children: React.ReactNode;
};

/**
 * The layer the paths are drawn in: `VIEW_WIDTH` units across whatever the width of the plot, and
 * real pixels down. Strokes keep their thickness because each path opts out of the stretch.
 */
export function PathLayer({ height, className, children }: PathLayerProps) {
  return (
    <svg
      aria-hidden='true'
      viewBox={`0 0 ${VIEW_WIDTH} ${height}`}
      preserveAspectRatio='none'
      className={cn(
        'pointer-events-none absolute inset-0 size-full overflow-visible',
        className
      )}
    >
      {children}
    </svg>
  );
}

